// ----------------------------------------------------------
// NYC Bus Infrastructure Map
// Static data generated by GitHub Actions
// ----------------------------------------------------------

// ----------------------------------------------------------
// Map Initialization
// ----------------------------------------------------------

const map = L.map("map", {
  preferCanvas: true
}).setView([40.71, -74.00], 12);

L.tileLayer(
  "https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png",
  {
    attribution: "© OpenStreetMap contributors © CARTO",
    maxZoom: 19
  }
).addTo(map);

// ----------------------------------------------------------
// Layers
// ----------------------------------------------------------

const busStopsLayer = L.layerGroup();
const busRoutesLayer = L.layerGroup();
const busSignsLayer = L.layerGroup();
const busLanesLayer = L.layerGroup();

busStopsLayer.addTo(map);
busRoutesLayer.addTo(map);
busSignsLayer.addTo(map);
busLanesLayer.addTo(map);

L.control.layers(
  null,
  {
    "Bus Stops": busStopsLayer,
    "Bus Routes": busRoutesLayer,
    "Bus Signs": busSignsLayer,
    "Bus Lanes": busLanesLayer
  },
  {
    collapsed: false
  }
).addTo(map);

// ----------------------------------------------------------
// Utilities
// ----------------------------------------------------------

async function fetchJSON(url) {
  const resp = await fetch(url, {
    cache: "no-store"
  });

  if (!resp.ok) {
    throw new Error(`${url}: ${resp.status}`);
  }

  return resp.json();
}

function safeNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function fitToInfrastructure() {
  const groups = [
    busRoutesLayer,
    busStopsLayer,
    busLanesLayer
  ];

  let bounds = null;

  groups.forEach(layer => {
    if (
      layer.getLayers &&
      layer.getLayers().length > 0 &&
      layer.getBounds
    ) {
      const b = layer.getBounds();

      if (b.isValid()) {
        bounds = bounds ? bounds.extend(b) : b;
      }
    }
  });

  if (bounds?.isValid()) {
    map.fitBounds(bounds, {
      padding: [20, 20]
    });
  }
}

// ----------------------------------------------------------
// Coordinate Conversion
// ----------------------------------------------------------

/**
 * Convert from EPSG:2260 (NAD_1983_StatePlane_New_York_Long_Island_FIPS_3104_Feet)
 * to WGS84 (lat/lon)
 *
 * Projection: Lambert Conformal Conic (2SP)
 * Parameters (EPSG:2260):
 *  - Latitude of 1st standard parallel: 40.66666666666666
 *  - Latitude of 2nd standard parallel: 41.03333333333333
 *  - Latitude of origin: 40.16666666666666
 *  - Central meridian: -74.0
 *  - False easting: 984250.0 (US survey feet)
 *  - False northing: 0.0 (US survey feet)
 *
 * This implementation performs the inverse Lambert Conformal Conic (2SP) projection
 * on the NAD83 ellipsoid and converts US survey feet to meters.
 * It's a direct implementation of the Snyder formulas with an iterative solution
 * to recover latitude from the isometric latitude (t).
 */
function epsg2260ToWGS84(x_ft, y_ft) {
  // EPSG:2260 LCC parameters
  const lat1 = 40.66666666666666 * Math.PI / 180; // first standard parallel (radians)
  const lat2 = 41.03333333333333 * Math.PI / 180; // second standard parallel (radians)
  const lat0 = 40.16666666666666 * Math.PI / 180; // latitude of origin (radians)
  const lon0 = -74.0 * Math.PI / 180; // central meridian (radians)

  // False easting / northing in US survey feet (EPSG uses US survey feet)
  const x0_ft = 984250.0;
  const y0_ft = 0.0;

  // Convert US survey feet to meters
  const usFtToMeters = 0.3048006096012192; // exact conversion for US survey foot

  const x = (x_ft - x0_ft) * usFtToMeters;
  const y = (y_ft - y0_ft) * usFtToMeters;

  // NAD83 / GRS80 ellipsoid constants
  const a = 6378137.0; // semi-major axis (meters)
  const f = 1 / 298.257222101; // flattening for GRS80
  const e = Math.sqrt(2 * f - f * f); // eccentricity

  function m(phi) {
    return Math.cos(phi) / Math.sqrt(1 - (e * e) * Math.sin(phi) * Math.sin(phi));
  }

  function t(phi) {
    const sinp = Math.sin(phi);
    const part = (1 - e * sinp) / (1 + e * sinp);
    return Math.tan(Math.PI / 4 - phi / 2) / Math.pow(part, e / 2);
  }

  const m1 = m(lat1);
  const m2 = m(lat2);
  const t1 = t(lat1);
  const t2 = t(lat2);
  const t0 = t(lat0);

  // n, F, rho0 as per Snyder
  const n = Math.log(m1 / m2) / Math.log(t1 / t2);
  const F = m1 / (n * Math.pow(t1, n));
  const rho0 = a * F * Math.pow(t0, n);

  // compute rho and theta from x,y (note typical forward uses x = rho*sin(n*(lambda-lambda0)))
  const rho = Math.sqrt(x * x + Math.pow(rho0 - y, 2));
  const theta = Math.atan2(x, rho0 - y);

  // compute t from rho
  const tVal = Math.pow(rho / (a * F), 1 / n);

  // iterative solution to recover phi from t
  let phi = Math.PI / 2 - 2 * Math.atan(tVal); // initial guess

  for (let i = 0; i < 15; i++) {
    const esin = e * Math.sin(phi);
    const phiNext = Math.PI / 2 - 2 * Math.atan(tVal * Math.pow((1 - esin) / (1 + esin), e / 2));
    if (Math.abs(phiNext - phi) < 1e-12) {
      phi = phiNext;
      break;
    }
    phi = phiNext;
  }

  const lat = phi * 180 / Math.PI;
  const lon = (lon0 + theta / n) * 180 / Math.PI;

  return [lat, lon];
}

// ----------------------------------------------------------
// Cached GTFS Data
// ----------------------------------------------------------

async function loadCachedGTFS() {
  try {
    const [stops, shapes] = await Promise.all([
      fetchJSON("data/stops.json"),
      fetchJSON("data/shapes.json")
    ]);

    drawStops(stops);
    drawShapes(shapes);

    console.log(
      `Loaded ${stops.length} stops and ${shapes.length} shapes`
    );
  } catch (err) {
    console.error("GTFS cache load failed:", err);
  }
}

// ----------------------------------------------------------
// Stops
// ----------------------------------------------------------

function drawStops(stops) {
  stops.forEach(stop => {
    const lat = safeNumber(stop.lat);
    const lon = safeNumber(stop.lon);

    if (lat === null || lon === null) return;

    // Use a light blue for bus stop markers
    L.circleMarker([lat, lon], {
      radius: 3,
      color: "#66CCFF",
      fillColor: "#66CCFF",
      fillOpacity: 0.7,
      weight: 1
    })
      .bindTooltip(stop.stop_name || stop.stop_id || "")
      .addTo(busStopsLayer);
  });
}

// ----------------------------------------------------------
// Route Shapes
// ----------------------------------------------------------

function drawShapes(shapes) {
  shapes.forEach(shape => {
    if (!Array.isArray(shape.points)) return;

    const pts = shape.points
      .map(p => {
        if (Array.isArray(p)) {
          return [Number(p[0]), Number(p[1])];
        }

        return [
          Number(p.lat),
          Number(p.lon)
        ];
      })
      .filter(
        p =>
          Number.isFinite(p[0]) &&
          Number.isFinite(p[1])
      );

    if (pts.length < 2) return;

    L.polyline(pts, {
      color: "#6f42c1",
      weight: 2,
      opacity: 0.6
    })
      .bindTooltip(shape.route_id || "")
      .addTo(busRoutesLayer);
  });
}

// ----------------------------------------------------------
// NYC DOT Bus Signs
// ----------------------------------------------------------

async function loadBusSigns() {
  try {
    const url =
      "https://data.cityofnewyork.us/resource/qt6m-xctn.json" +
      "?$select=sign_x_coord,sign_y_coord,sign_description,order_completed_on_date" +
      "&$where=(upper(sign_description)%20like%20'%25BUS%20STOP%25'%20OR%20upper(sign_description)%20like%20'%25BUS%20LANE%25'%20OR%20upper(sign_description)%20like%20'%25BUSES%20ONLY%25')%20AND%20record_type%20=%20'Current'" +
      "&$limit=50000";

    const data = await fetchJSON(url);

    data.forEach(sign => {
      const x = safeNumber(sign.sign_x_coord);
      const y = safeNumber(sign.sign_y_coord);

      if (x === null || y === null) return;

      // Convert from EPSG:2260 to WGS84
      const [lat, lon] = epsg2260ToWGS84(x, y);

      if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;

      const desc = (sign.sign_description || "").toUpperCase();

      // Color bus lane signs indigo, bus stop signs light blue
      const signColor = desc.includes("LANE")
        ? "#4B0082" // indigo
        : desc.includes("STOP")
        ? "#66CCFF" // light blue
        : "#6c757d"; // default gray

      const tooltipText = sign.order_completed_on_date
        ? `${sign.sign_description}<br>Completed: ${sign.order_completed_on_date}`
        : sign.sign_description || "Bus Sign";

      L.circleMarker([lat, lon], {
        radius: 4,
        color: signColor,
        fillColor: signColor,
        fillOpacity: 0.8,
        weight: 1
      })
        .bindTooltip(tooltipText)
        .addTo(busSignsLayer);
    });

    console.log(`Loaded ${data.length} bus signs`);
  } catch (err) {
    console.error("Bus signs load failed:", err);
  }
}

// ----------------------------------------------------------
// NYC DOT Bus Lanes
// ----------------------------------------------------------

async function loadBusLanes() {
  try {
    const url =
      "https://data.cityofnewyork.us/resource/ycrg-ses3.json?$limit=50000";

    const rows = await fetchJSON(url);

    const features = rows
      .filter(r => r.the_geom)
      .map(r => {
        let geom = r.the_geom;

        if (typeof geom === "string") {
          try {
            geom = JSON.parse(geom);
          } catch {
            return null;
          }
        }

        return {
          type: "Feature",
          geometry: geom,
          properties: r
        };
      })
      .filter(Boolean);

    L.geoJSON(
      {
        type: "FeatureCollection",
        features
      },
      {
        style: {
          color: "#f77f00",
          weight: 3,
          opacity: 0.8
        }
      }
    ).addTo(busLanesLayer);

    console.log(
      `Loaded ${features.length} bus lane features`
    );
  } catch (err) {
    console.error("Bus lanes load failed:", err);
  }
}

// ----------------------------------------------------------
// Initialization
// ----------------------------------------------------------

async function init() {
  console.log("Loading bus infrastructure layers...");

  const results = await Promise.allSettled([
    loadCachedGTFS(),
    loadBusSigns(),
    loadBusLanes()
  ]);

  results.forEach(result => {
    if (result.status === "rejected") {
      console.error(result.reason);
    }
  });

  fitToInfrastructure();

  console.log("Map initialization complete");
}

init();
